using System.IO.Compression;
using System.Text;
using DiscForge.Core.Fat;
using Xunit;

namespace DiscForge.Core.Tests;

public class FatReaderTests
{
    // A real, minimal FAT16 volume built with mkfs.fat (gzipped + base64): root has HELLO.TXT and a
    // subdirectory SUB containing "Long Name.txt" (a VFAT long file name).
    private const string Fat16ImageGz =
        "";

    private static byte[] Image()
    {
        var gz = System.Convert.FromBase64String(Fat16ImageGz);
        using var inMs = new MemoryStream(gz);
        using var gzs = new GZipStream(inMs, CompressionMode.Decompress);
        using var outMs = new MemoryStream();
        gzs.CopyTo(outMs);
        return outMs.ToArray();
    }

    [Fact]
    public void Detects_and_reads_a_real_fat16_volume()
    {
        var data = Image();
        Assert.True(FatReader.IsFat(data));
        var vol = FatReader.Read(data);
        Assert.Equal(FatType.Fat16, vol.Type);
        Assert.Equal("MINI16", vol.VolumeLabel);
    }

    [Fact]
    public void Enumerates_files_directories_and_long_names()
    {
        var vol = FatReader.Read(Image());
        Assert.Contains(vol.Files, f => f.Path == "/HELLO.TXT");
        Assert.Contains(vol.Directories, d => d.Name == "SUB");
        // The VFAT long name is reassembled (not the mangled 8.3 alias).
        Assert.Contains(vol.Files, f => f.Path == "/SUB/Long Name.txt");
    }

    [Fact]
    public void Extracts_file_contents_by_cluster_chain()
    {
        var data = Image();
        var vol = FatReader.Read(data);
        var hello = Assert.Single(vol.Files, f => f.Path == "/HELLO.TXT");
        var text = Encoding.ASCII.GetString(FatReader.ExtractFile(data, hello));
        Assert.StartsWith("DiscForge FAT16 test", text);
    }

    [Fact]
    public void Garbage_is_rejected_not_crashed()
    {
        Assert.False(FatReader.IsFat(new byte[512]));
        Assert.Throws<FatFormatException>(() => FatReader.Read(new byte[512]));
    }
}
